SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2020.YEAR, Станции2020.NUST, Станции2020.nr, Станции2020.E, Станции2020.EOTP, Станции2020.EURT, Станции2020.EUST, Станции2020.Q, Станции2020.TURT, Станции2020.TUST, Станции2020.B, Станции2020.GAZ, Доп_угли2020.gazpp, Станции2020.MAZUT, Станции2020.TORF, Станции2020.SLAN, Станции2020.PROCH, Станции2020.UGOL, Станции2020.DON, Станции2020.PODM, Станции2020.PECH, Доп_угли2020.intin, Доп_угли2020.vork, Станции2020.ARKT, Станции2020.KUZN, Доп_угли2020.kuzngd, Доп_угли2020.kuznt, Доп_угли2020.kuznss, Доп_угли2020.kuznun, Станции2020.URAL, Доп_угли2020.sver, Доп_угли2020.chel, Доп_угли2020.kizel, Станции2020.BASHK, Станции2020.KAZAH, Доп_угли2020.ekib, Доп_угли2020.maikub, Станции2020.KAN, Доп_угли2020.nazar, Доп_угли2020.ibor, Доп_угли2020.berez, Доп_угли2020.per, Доп_угли2020.irbei, Доп_угли2020.kansk, Станции2020.TUNG, Доп_угли2020.jer, Доп_угли2020.karab, Станции2020.IRKUT, Доп_угли2020.azey, Доп_угли2020.mug, Доп_угли2020.cher, Станции2020.HAK, Станции2020.TUV, Станции2020.BUR, Доп_угли2020.gusin, Доп_угли2020.tugn, Доп_угли2020.okino, Станции2020.CHIT, Доп_угли2020.har, Доп_угли2020.urt, Доп_угли2020.tataur, Доп_угли2020.tarbag, Доп_угли2020.zab_kam, Станции2020.YAKUT, Доп_угли2020.neru, Доп_угли2020.zyryan, Доп_угли2020.pyak, Станции2020.AMUR, Доп_угли2020.rai, Доп_угли2020.erk, Станции2020.URG, Станции2020.USHUM, Станции2020.PRIM, Доп_угли2020.bikin, Доп_угли2020.razdol, Доп_угли2020.hankai, Станции2020.MAG, Станции2020.SAH, Станции2020.KAMCH, Станции2020.CHUKOT, Доп_угли2020.anad, Доп_угли2020.bering, Станции2020.QOTR, Станции2020.SNK, Станции2020.EWTP, Станции2020.NT, Станции2020.OBOR, Станции2020.VED, Станции2020.OBL, Станции2020.DEP, Станции2020.OES, Станции2020.ER, Станции2020.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2020.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип, Станции2020.SNt
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2020 LEFT JOIN Доп_угли2020 ON (Станции2020.YEAR=Доп_угли2020.YEAR) AND (Станции2020.NUMB1120=Доп_угли2020.NUMB1120)) ON Имена_ОЭС.oes=Станции2020.OES) ON Имена_областей.OBL=Станции2020.OBL) ON Имена_станций.NUMB=Станции2020.NUMB1120) LEFT JOIN имена_ГК ON Станции2020.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2020.BE=имена_БЕ.code;
